const stories=[{tag:'ИСТОРИЯ ИЗ ВАШЕГО ПРОЕКТА',title:'Аня & Никита',text:'Знакомство, переписки, первое свидание — и маленькие приключения, из которых складывается большая история вдвоём.',tags:['Знакомство','Свидания','Ваши шутки'],note:'Сюжет из обсуждения проекта. Иллюстрация — концепт оформления, не страницы готового заказа.'},{tag:'ИДЕЯ ДЛЯ ВАШЕГО КОМИКСА',title:'Наш первый год',text:'От неловкого первого свидания до общих привычек. Двенадцать месяцев, в которых так много поводов сказать: «Помнишь?»',tags:['Годовщина','Первые моменты','Общие привычки'],note:'Демонстрационный сюжет для вдохновения. Иллюстрация показывает возможный стиль, а не выполненный заказ.'},{tag:'ИДЕЯ ДЛЯ ВАШЕГО КОМИКСА',title:'Просто быть рядом',text:'Готовить завтрак, спорить о фильме и держаться за руки по дороге домой. Комикс о той самой любви, которая прячется в мелочах.',tags:['Без повода','Повседневность','Только для двоих'],note:'Демонстрационный сюжет для вдохновения. Иллюстрация показывает возможный стиль, а не выполненный заказ.'}];
document.querySelectorAll('[data-story]').forEach(button=>button.addEventListener('click',()=>{const s=stories[Number(button.dataset.story)];document.querySelectorAll('[data-story]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});for(const field of ['tag','title','text','note'])document.getElementById('case-'+field).textContent=s[field];document.getElementById('case-tags').replaceChildren(...s.tags.map(t=>{const span=document.createElement('span');span.textContent=t;return span}));}));
const dialog=document.getElementById('art-dialog');document.getElementById('case-open').addEventListener('click',()=>dialog.showModal());document.querySelector('.dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.getElementById('brief-form').addEventListener('submit',e=>{e.preventDefault();const data=new FormData(e.currentTarget);const name=String(data.get('name')).trim(),story=String(data.get('story')).trim();if(!name||!story){document.getElementById(!name?'name':'story').focus();return}document.getElementById('brief-output').value=`Здравствуйте! Хочу персональный комикс.\n\nМеня зовут: ${name}\nПовод: ${data.get('occasion')}\nМоя идея: ${story}\n\nОриентир бюджета: около 3 000 ₽. Хочу уточнить объём, печать и сроки.`;document.getElementById('brief-result').hidden=false;document.getElementById('copy-status').textContent='Заявка не отправлена. Скопируйте текст для сообщения.';document.getElementById('brief-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'})});
document.getElementById('copy-brief').addEventListener('click',async()=>{const output=document.getElementById('brief-output');try{await navigator.clipboard.writeText(output.value);document.getElementById('copy-status').textContent='Текст скопирован. Его можно вставить в сообщение.'}catch{output.focus();output.select();document.getElementById('copy-status').textContent='Выделили текст. Скопируйте его вручную.'}});
